/**
 * @file Main JavaScript file for the RAICA application.
 * @description This file initializes Alpine.js stores and components for managing
 * authentication, chat, and agent interactions. It handles all client-side logic,
 * API communication, and real-time updates via Server-Sent Events.
 * @version 1.0.0
 */

/**
 * A wrapper around the Fetch API to streamline API calls.
 * Automatically adds Authorization headers, handles JSON parsing, and provides
 * consistent error handling.
 *
 * @param {string} url The URL to fetch.
 * @param {RequestInit} [options={}] Fetch options (method, body, etc.).
 * @returns {Promise<any>} A promise that resolves with the JSON response.
 * @throws {Error} Throws an error for network issues or non-2xx responses.
 */
const apiFetch = async (url, options = {}) => {
    const headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        ...options.headers,
    };

    const token = Alpine.store('auth').token;
    if (token) {
        headers['Authorization'] = `Bearer ${token}`;
    }

    // For FormData, let the browser set the Content-Type header with the boundary
    if (options.body instanceof FormData) {
        delete headers['Content-Type'];
    }

    const config = {
        ...options,
        headers,
    };

    try {
        const response = await fetch(url, config);

        if (!response.ok) {
            if (response.status === 401) {
                // Handle unauthorized access by logging out and redirecting
                Alpine.store('auth').performLogout();
                window.location.href = '/login';
            }
            const errorData = await response.json().catch(() => ({ message: response.statusText }));
            throw new Error(errorData.detail || errorData.message || `HTTP error! status: ${response.status}`);
        }

        // Handle responses with no content (e.g., 204 No Content)
        if (response.status === 204) {
            return null;
        }

        return await response.json();
    } catch (error) {
        console.error('API Fetch Error:', error);
        // Re-throw the error to be caught by the calling component's try/catch block
        throw error;
    }
};


