                try {
                    const statusResponse = await apiFetch(`/api/agents/status/${executionId}`);
                    Alpine.store('agents').currentExecution = { ...Alpine.store('agents').currentExecution, ...statusResponse };
                    if (['completed', 'failed', 'cancelled'].includes(statusResponse.status)) {
                        this.cancelPolling();
                    }
                } catch (error) {
                    console.error('Polling failed:', error);
                    Alpine.store('agents').currentExecution.status = 'failed';
                    this.cancelPolling();
                }
            }, 2000);
        },
        cancelPolling() {
            if (this.pollingIntervalId) {
                clearInterval(this.pollingIntervalId);
                this.pollingIntervalId = null;
            }
        }
    }));

    /**
     * @component bottom_status_bar
     * @description Displays agent status and provides a cancel action.
     */
    Alpine.data('bottom_status_bar', () => ({
        isCancelling: false,
        async cancelAgent() {
            const agentStore = Alpine.store('agents');
            const executionId = agentStore.currentExecution.id;
            if (!executionId || this.isCancelling) return;

            this.isCancelling = true;
            try {
                await apiFetch(`/api/agents/stop/${executionId}`, { method: 'POST' });
                agentStore.currentExecution.status = 'cancelled';
            } catch (error) {
                console.error('Failed to cancel agent execution:', error);
                alert('Could not cancel the agent execution.');
            } finally {
                this.isCancelling = false;
            }
        }
    }));
