<script>
    function chatApp() {
        return {
            // --- STATE ---
            conversations: [
                { id: 1, title: 'Getting Started with RAICA' },
                { id: 2, title: 'Python Data Analysis' },
                { id: 3, title: 'Tailwind CSS Tips' }
            ],
            currentConversationId: 1,
            messages: [
                { role: 'ai', content: 'Hello! I am RAICA, your RAG AI Context Agency. How can I assist you today?' }
            ],
            newMessage: '',
            isLoading: false,
            error: null,
            agents: [
                { id: 'default', name: 'General Assistant', description: 'A helpful AI for general queries and tasks.' },
                { id: 'coder', name: 'Code Helper', description: 'Specialized in writing, debugging, and explaining code.' },
                { id: 'researcher', name: 'Research Analyst', description: 'Expert in finding and summarizing information from contexts.' }
            ],
            selectedAgentId: 'default',
            showLeftSidebar: false,
            showRightSidebar: false,
            eventSource: null,

            // --- METHODS ---
            init() {
                console.log('Chat app initialized.');
                this.$watch('messages', () => this.scrollToBottom());
            },

            sendMessage() {
                if (this.isLoading || !this.newMessage.trim()) return;

                this.isLoading = true;
                this.error = null;
                const userMessageContent = this.newMessage.trim();
                this.messages.push({ role: 'user', content: userMessageContent });
                this.newMessage = '';
                this.autoResizeTextarea({ target: this.$el.querySelector('textarea') });

                // Add a placeholder for the AI response that we will populate
                this.messages.push({ role: 'ai', content: '' });
                this.scrollToBottom();

                // Establish SSE connection
                const queryParams = new URLSearchParams({
                    prompt: userMessageContent,
                    agent_id: this.selectedAgentId
                });
                this.eventSource = new EventSource(`{{ url_for('main.stream') }}?${queryParams.toString()}`);

                this.eventSource.onmessage = (event) => {
                    try {
                        const data = JSON.parse(event.data);
                        if (data.type === 'chunk' && data.content) {
                            // Append the token to the last AI message
                            this.messages[this.messages.length - 1].content += data.content;
                            this.scrollToBottom();
                        } else if (data.type === 'error') {
                            this.handleStreamError(data.content);
                        }
                    } catch (e) {
                        console.error("Failed to parse SSE message data:", event.data, e);
                    }
                };

                this.eventSource.onerror = (err) => {
                    console.error("EventSource failed:", err);
                    this.handleStreamError("Connection to the server was lost. Please check your connection and try again.");
                };

                this.eventSource.addEventListener('end', (event) => {
                    this.closeStream();
                });
            },

            handleStreamError(errorMessage) {
                this.error = errorMessage;
                // Remove the empty AI message placeholder on error
                if (this.messages[this.messages.length - 1].role === 'ai' && this.messages[this.messages.length - 1].content === '') {
                    this.messages.pop();
                }
                this.closeStream();
            },

            closeStream() {
                if (this.eventSource) {
                    this.eventSource.close();
                    this.eventSource = null;
                }
                this.isLoading = false;
                console.log('Stream closed.');
            },

            scrollToBottom() {
                this.$nextTick(() => {
                    const chatWindow = this.$refs.chatWindow;
                    if (chatWindow) {
                        chatWindow.scrollTo({ top: chatWindow.scrollHeight, behavior: 'smooth' });
                    }
                });
            },

            autoResizeTextarea(event) {
                event.target.style.height = 'auto';
                // Set a max height to prevent infinite growth
                const maxHeight = 200; 
                event.target.style.height = Math.min(event.target.scrollHeight, maxHeight) + 'px';
            },

            newChat() {
                this.messages = [{ role: 'ai', content: 'New chat started. How can I help?' }];
                this.currentConversationId = Date.now(); // Simple unique ID for new chat
                this.conversations.push({ id: this.currentConversationId, title: 'New Chat' });
                this.newMessage = '';
                this.error = null;
                if (this.isLoading) {
                    this.closeStream();
                }
            },

            selectConversation(id) {
                console.log(`Switched to conversation ${id}`);
                this.currentConversationId = id;
                // In a real app, you would fetch the messages for this conversation
                this.messages = [
                    { role: 'ai', content: `This is conversation history for ID ${id}. Ask me anything!` }
                ];
            },

            selectAgent(id) {
                this.selectedAgentId = id;
                console.log(`Agent switched to: ${id}`);
            },

            // --- GETTERS / COMPUTED ---
            selectedAgent() {
                return this.agents.find(a => a.id === this.selectedAgentId) || this.agents[0];
            }
        }
    }
</script>
