<script>
    function registerForm() {
        return {
            formData: {
                username: '',
                email: '',
                password: '',
                confirm_password: ''
            },
            errors: {},
            loading: false,
            showPassword: false,
            showConfirmPassword: false,
            passwordStrength: {
                score: 0,
                text: 'Too weak',
                color: 'bg-gray-200 dark:bg-gray-600',
                textColor: 'text-gray-500 dark:text-gray-400'
            },

            validateField(field) {
                // Clear previous error
                delete this.errors[field];

                switch (field) {
                    case 'username':
                        if (!this.formData.username) {
                            this.errors.username = 'Username is required.';
                        } else if (this.formData.username.length < 3) {
                            this.errors.username = 'Username must be at least 3 characters long.';
                        }
                        break;
                    case 'email':
                        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        if (!this.formData.email) {
                            this.errors.email = 'Email is required.';
                        } else if (!emailRegex.test(this.formData.email)) {
                            this.errors.email = 'Please enter a valid email address.';
                        }
                        break;
                    case 'password':
                        this.calculatePasswordStrength();
                        if (!this.formData.password) {
                            this.errors.password = 'Password is required.';
                        } else if (this.formData.password.length < 8) {
                            this.errors.password = 'Password must be at least 8 characters long.';
                        }
                        // Also re-validate confirm password if password changes
                        if (this.formData.confirm_password) {
                            this.validateField('confirm_password');
                        }
                        break;
                    case 'confirm_password':
                        if (!this.formData.confirm_password) {
                            this.errors.confirm_password = 'Please confirm your password.';
                        } else if (this.formData.password !== this.formData.confirm_password) {
                            this.errors.confirm_password = 'Passwords do not match.';
                        }
                        break;
                }
            },

            calculatePasswordStrength() {
                const pass = this.formData.password;
                let score = 0;
                if (!pass) {
                    this.passwordStrength = { score: 0, text: 'Too weak', color: 'bg-gray-200 dark:bg-gray-600', textColor: 'text-gray-500 dark:text-gray-400' };
                    return;
                }

                if (pass.length >= 8) score++;
                if (pass.match(/[a-z]/)) score++;
                if (pass.match(/[A-Z]/)) score++;
                if (pass.match(/[0-9]/)) score++;
                if (pass.match(/[^a-zA-Z0-9]/)) score++; // Special character

                // Adjust score to be out of 4
                this.passwordStrength.score = Math.min(score, 4);

                switch (this.passwordStrength.score) {
                    case 0:
                    case 1:
                        this.passwordStrength.text = 'Weak';
                        this.passwordStrength.color = 'bg-red-500';
                        this.passwordStrength.textColor = 'text-red-500 dark:text-red-400';
                        break;
                    case 2:
                        this.passwordStrength.text = 'Fair';
                        this.passwordStrength.color = 'bg-yellow-500';
                        this.passwordStrength.textColor = 'text-yellow-500 dark:text-yellow-400';
                        break;
                    case 3:
                        this.passwordStrength.text = 'Good';
                        this.passwordStrength.color = 'bg-blue-500';
                        this.passwordStrength.textColor = 'text-blue-500 dark:text-blue-400';
                        break;
                    case 4:
                        this.passwordStrength.text = 'Strong';
                        this.passwordStrength.color = 'bg-green-500';
                        this.passwordStrength.textColor = 'text-green-500 dark:text-green-400';
                        break;
                }
            },

            get isFormValid() {
                return Object.keys(this.errors).length === 0 &&
                       this.formData.username &&
                       this.formData.email &&
                       this.formData.password &&
                       this.formData.confirm_password;
            },

            submitForm() {
                // Run all validations before submitting
                Object.keys(this.formData).forEach(field => this.validateField(field));

                if (this.isFormValid) {
                    this.loading = true;
                    this.$el.submit(); // 'this.$el' refers to the form element
                }
            }
        }
    }
</script>
